
(()=>{'use strict';
const task=window.__taskBootstrap.v0, episode=window.__taskBootstrap.v1;
let world=null, route='product/desk-pair', draft=null, dirty=false, baseVersion=0, lastVersion=-1, lastGeneration=-1, modal=null, orderExpanded=false;
const app=document.getElementById('app'),overlay=document.getElementById('overlay');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=c=>(c/100).toFixed(2),title=s=>s.charAt(0).toUpperCase()+s.slice(1),clone=x=>JSON.parse(JSON.stringify(x));
const badge=s=>`<span class="badge ${esc(s.toLowerCase())}">${esc(title(s))}</span>`;
const art=(key,large=false)=>`<div class="art ${large?'large':''}"><div class="${key==='mat'?'mat':key==='pouch'?'pouch':'pen'}-shape"></div></div>`;
const nav=(where,text)=>`<a href="#${where}" data-route="${where}">${esc(text)}</a>`;
// Status is a row of plain option buttons rather than a native <select>: the browser's option popup
// is unlabelled 24 px rows that the desktop harness can only hit by coordinates.
const STATUSES=['active','draft','archived','unlisted'];
const statusPicker=(value,label)=>`<div class="status-options" role="radiogroup" aria-label="${label}">${STATUSES.map(x=>`<button type="button" class="status-option ${value===x?'current':''}" role="radio" aria-checked="${value===x}" data-status="${x}">${title(x)}</button>`).join('')}</div>`;
const hms=s=>{const t=16*3600+Math.max(0,Math.floor(s));return `${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;};
const CLOSED={first_order_missed:'Campaign closed: the first promotion order could not be placed.',first_order_wrong_terms:'Campaign closed: the first promotion order used other terms.',last_order_missed:'Campaign closed: a promotion order could not be placed.',last_order_wrong_terms:'Campaign closed: a promotion order used other terms.',campaign_ended:'Campaign ended.'};
// Whole seconds only, each countdown in its own element; `now` is a declared clock field, so these
// ticks never change the episode version.
function renderClock(s){const w=s.world,now=Math.floor(w.now),$=id=>document.getElementById(id);$('clock-time').textContent=hms(now);$('first-at').textContent=hms(w.first_orders_at);$('first-left').textContent=now<w.first_orders_at?`in ${w.first_orders_at-now} s`:'passed';$('end-at').textContent=hms(w.campaign_ends_at);$('end-left').textContent=now<w.campaign_ends_at?`in ${w.campaign_ends_at-now} s`:'ended';const phase=$('clock-phase'),text=s.phase==='resolved'?'Campaign complete.':s.phase==='expired'?(CLOSED[s.terminal_reason]||'Campaign closed.'):'';phase.textContent=text;phase.hidden=!text;phase.classList.toggle('closed',s.phase==='expired');}
const priceInput=(key,value,field='price',title=key)=>`<label class="price-wrap" role="group"><span>$</span><input type="text" inputmode="decimal" aria-label="${esc(title)} price" data-edit="${field}" data-key="${esc(key)}" value="${cash(value)}"></label>`;
function initDraft(){if(!world)return;dirty=false;baseVersion=rt.state.version;if(route==='bundle'){draft={components:clone(world.parent.components),combined:world.parent.combined};for(const [key,item]of Object.entries(draft.components)){item.selected=world.products[key].variants.filter(v=>item.selected[v.id]===v.color).map(v=>v.id);}}else if(route==='product/desk-pair')draft={status:world.parent.status,online:world.parent.online,prices:Object.fromEntries(world.parent.variants.map(v=>[v.key,v.price]))};else if(route.startsWith('product/')){const p=world.products[route.split('/')[1]];draft=p?{prices:Object.fromEntries(p.variants.map(v=>[v.id,v.price]))}:{status:world.other.status};}else draft=null;}
function go(next){if(dirty&&next!==route){modal={type:'leave',next};renderModal();return;}route=next;modal=null;orderExpanded=false;initDraft();render();window.scrollTo(0,0);}
function notices(){return world.notices.length?`<div class="warn"><div class="notice-title">Some product options have changed</div>${world.notices.map(n=>`${esc(world.products[n.product].title)} no longer has the selected Color value “${esc(n.previous)}”.`).join('<br>')}<div style="margin-top:7px">This bundle is now a draft.</div></div>`:'';}
function freshness(){return dirty&&baseVersion!==rt.state.version?'<div class="update-note">The catalog was updated while you were editing.<button id="reload">Reload current details</button></div>':'';}
function render(){if(!world)return;document.querySelectorAll('aside [data-route]').forEach(e=>e.classList.toggle('active',e.dataset.route===(route==='bundle'?'bundle':route.startsWith('order')?'orders':'products')));document.getElementById('savebar').hidden=!dirty||route==='bundle';app.innerHTML=freshness()+(route==='bundle'?bundleView():route==='products'?productsView():route==='orders'?ordersView():route.startsWith('order/')?orderView(route.slice(6)):productView(route.slice(8)));renderModal();}
function productView(key){if(key==='desk-pair')return parentView();const p=world.products[key];if(!p)return `<div class="heading"><button data-route="products" aria-label="Back to products">←</button><h1>Pen rest</h1>${badge(world.other.status)}</div><div class="columns"><section class="card pad"><h2>Media</h2>${art('pen',true)}<p>Desktop accessory</p><h2>Price</h2><p>$${cash(world.other.price)}</p></section><section class="card pad"><h2>Status</h2>${statusPicker(draft.status,'Pen rest status')}</section></div>`;return `<div class="heading"><button data-route="products" aria-label="Back to products">←</button><h1>${esc(p.title)}</h1>${badge(p.status)}<span class="spacer"></span>${nav('product/desk-pair','Desk pair')}</div><div class="columns"><div><section class="card pad"><label class="field"><span>Title</span><input class="full" type="text" value="${esc(p.title)}" readonly></label><h2>Media</h2>${art(key,true)}</section><section class="card"><div class="pad"><h2>Variants</h2><span class="badge">Color</span></div><table><thead><tr><th>Variant</th><th>Price</th><th>Available</th></tr></thead><tbody>${p.variants.map(v=>`<tr><td>${esc(v.color)}</td><td>${priceInput(v.id,draft.prices[v.id],'component-price',v.color)}</td><td>${v.stock}</td></tr>`).join('')}</tbody></table></section><p class="muted tiny">${esc(p.updated)}</p></div><div><section class="card pad"><h2>Status</h2>${badge(p.status)}</section><section class="card pad"><h2>Publishing</h2><p>◉ Online Store</p></section><section class="card pad"><h2>Included in bundles</h2>${nav('product/desk-pair','Desk pair')}</section></div></div>`;}
function parentView(){const p=world.parent;return `<div class="heading"><button data-route="products" aria-label="Back to products">←</button><h1>Desk pair</h1>${badge(p.status)}<span class="spacer"></span><span class="muted tiny">Product</span></div>${notices()}<div class="columns"><div><section class="card pad"><label class="field"><span>Title</span><input class="full" type="text" value="Desk pair" readonly></label><label class="field"><span>Description</span><div class="description">${esc(p.description)}</div></label><h2>Media</h2><div class="media">${art('mat',true)}${art('pouch',true)}</div></section><section class="card"><div class="pad row"><span class="app-mark">▦</span><h2 style="margin:0">Bundled products</h2><span class="spacer"></span><button id="edit-bundle" data-route="bundle">Edit</button></div>${Object.entries(p.components).map(([k,c])=>`<div class="line row">${art(k)}<div>${nav('product/'+k,world.products[k].title)}<div class="muted tiny">Color</div></div><span class="spacer"></span><span>Quantity ${c.quantity}</span></div>`).join('')}<div class="line muted tiny">Managed by Bundles</div></section><section class="card"><div class="pad"><h2>Variants</h2><span class="badge">${p.combined?'Color':'Desk mat · Color'}</span>${p.combined?'':' <span class="badge">Cable pouch · Color</span>'}</div><table><thead><tr><th>Variant</th><th>Price</th><th>Available</th></tr></thead><tbody>${p.variants.map(v=>`<tr><td>${esc(v.title)}</td><td>${priceInput(v.key,draft.prices[v.key]??v.price,'price',v.title)}</td><td>${v.available}</td></tr>`).join('')}</tbody></table>${!p.variants.length?'<div class="empty">No variants</div>':''}<div class="muted tiny price-help" style="margin-top:14px">Bundle prices are maintained separately from component prices.</div></section></div><div><section class="card pad"><h2>Status</h2>${statusPicker(draft.status,'Desk pair status')}</section><section class="card pad"><div class="row"><h2 style="margin:0">Publishing</h2><span class="spacer"></span><button class="quiet" id="manage-publishing">Manage</button></div><p>${draft.online?'◉ Online Store':'Not published to any sales channel'}</p></section><section class="card pad"><h2>Product organization</h2><p class="muted tiny">Vendor</p><p>Fieldroom</p><p class="muted tiny">Product type</p><p>Desk accessories</p></section></div></div><div class="footer-actions"><button id="bottom-save" class="primary" ${dirty?'':'disabled'}>Save</button></div>`;}
function bundleView(){return `<div class="editor"><div class="heading"><button data-route="product/desk-pair" aria-label="Back to product">←</button><span class="app-mark">▦</span><h1>Bundles</h1><span class="spacer"></span><span class="muted">Desk pair</span></div>${notices()}<section class="card pad"><label class="field" style="margin-bottom:0"><span>Title</span><input class="title-input" type="text" value="Desk pair" readonly></label></section><section class="card"><div class="pad row"><h2 style="margin:0">Products</h2><span class="spacer"></span><button id="add-products">Select products</button></div>${Object.entries(draft.components).map(([key,c])=>`<div style="border-top:1px solid #e5e9ea"><div class="component-head">${art(key)}<div><strong>${esc(world.products[key].title)}</strong><div class="muted tiny">${world.products[key].variants.length} variants</div></div><span class="spacer"></span><label class="tiny muted">Quantity <input type="number" min="1" max="20" value="${c.quantity}" data-edit="quantity" data-key="${key}" aria-label="${esc(world.products[key].title)} quantity"></label><button class="quiet" data-remove="${key}" aria-label="Remove ${esc(world.products[key].title)}">×</button></div><div class="option-row"><span>Color</span><div class="pills">${world.products[key].variants.map(v=>`<label class="pill"><input type="checkbox" data-edit="option" data-product="${key}" data-key="${v.id}" ${c.selected.includes(v.id)?'checked':''}>${esc(v.color)}</label>`).join('')}</div></div></div>`).join('')}<div class="combine"><label><input id="combine-options" type="checkbox" data-edit="combined" ${draft.combined?'checked':''}>Combine options with matching names</label><p class="muted tiny" style="margin:8px 0 0 27px">Products with matching option names and values can share one selection.</p></div></section><div class="footer-actions"><button data-route="product/desk-pair">Cancel</button><button id="save-bundle" class="primary">Save and continue</button></div></div>`;}
function productsView(){return `<div class="heading"><h1>Products</h1></div><section class="card"><div class="tabs"><span>All</span></div><div class="pad"><input id="product-search" class="full" type="text" placeholder="Search products" aria-label="Search products"></div><table><thead><tr><th>Product</th><th>Status</th><th>Inventory</th><th>Type</th></tr></thead><tbody>${[{id:'desk-pair',title:'Desk pair',status:world.parent.status},...Object.values(world.products),{id:'other',...world.other}].map(p=>`<tr data-search="${esc(p.title.toLowerCase())}"><td><div class="row">${art(p.id==='desk-pair'?'mat':p.id)}${nav('product/'+p.id,p.title)}</div></td><td>${badge(p.status)}</td><td>${p.variants?p.variants.reduce((n,v)=>n+v.stock,0)+' available':p.id==='desk-pair'?'Bundle inventory':'24 available'}</td><td>Desk accessories</td></tr>`).join('')}</tbody></table></section>`;}
function ordersView(){return `<div class="heading"><h1>Orders</h1></div><section class="card"><div class="tabs"><span>All</span></div><table><thead><tr><th>Order</th><th>Date</th><th>Customer</th><th>Total</th><th>Payment status</th></tr></thead><tbody>${[...world.orders].reverse().map(o=>`<tr><td>${nav('order/'+encodeURIComponent(o.id),o.id)}</td><td>${o.at?`Today at 16:${String(Math.floor(o.at/60)).padStart(2,'0')}`:'Today at 15:48'}</td><td>${esc(o.customer||'Jamie Brooks')}</td><td>$${cash(o.total)}</td><td>${badge('Paid')}</td></tr>`).join('')}</tbody></table></section>`;}
function orderView(id){const o=world.orders.find(x=>x.id===decodeURIComponent(id));if(!o)return '<div class="empty">Order not found</div>';return `<div class="heading"><button data-route="orders" aria-label="Back to orders">←</button><h1>${esc(o.id)}</h1>${badge('Paid')}</div><div class="columns"><div><section class="card"><div class="pad"><h2>Unfulfilled</h2><div class="row">${art(o.components?'mat':'pen')}<strong>${esc(o.product||o.title)}</strong><span class="spacer"></span><span>1 × $${cash(o.total)}</span></div></div>${o.components?`<details ${orderExpanded?'open':''} id="order-components"><summary>${o.components.length} bundled products</summary>${o.components.map(c=>`<div class="order-component">${art(c.product)}<div>${esc(c.title)}<div class="muted">${esc(c.color)}</div></div><span class="spacer"></span><span>× ${c.quantity}</span></div>`).join('')}</details>`:''}</section><section class="card"><div class="pad"><h2>Paid</h2></div><div class="total"><span>Total</span><strong>$${cash(o.total)} USD</strong></div></section></div><section class="card pad"><h2>Customer</h2><p>${esc(o.customer||'Jamie Brooks')}</p><p class="muted tiny">Online Store</p></section></div>`;}
function renderModal(){if(!modal){overlay.innerHTML='';return;}let content='',heading='',foot='';if(modal.type==='publishing'){heading='Manage sales channels';content=`<label class="choice"><input id="channel-online" type="checkbox" ${draft.online?'checked':''}>Online Store</label>`;foot='<button id="close-modal">Cancel</button><button class="primary" id="done-publishing">Done</button>';}else if(modal.type==='products'){heading='Select products';content=`<div class="pad"><input id="select-search" class="full" type="text" placeholder="Search products"></div>${Object.values(world.products).map(p=>`<label class="choice" data-search="${esc(p.title.toLowerCase())}"><input type="checkbox" data-select-product="${p.id}" ${draft.components[p.id]?'checked':''}>${art(p.id)}<span>${esc(p.title)}<br><span class="muted tiny">${p.variants.length} variants</span></span></label>`).join('')}`;foot='<button id="close-modal">Cancel</button><button id="select-products" class="primary">Select</button>';}else{heading='Leave unsaved changes?';content='<div class="pad">Your changes will be lost if you leave this page.</div>';foot='<button id="close-modal">Keep editing</button><button id="leave-page" class="primary">Leave page</button>';}overlay.innerHTML=`<div class="dialog-shade"><section class="dialog" role="dialog" aria-modal="true" aria-label="${heading}"><div class="dialog-head"><h2>${heading}</h2></div>${content}<div class="dialog-foot">${foot}</div></section></div>`;}
function markDirty(){dirty=true;document.getElementById('savebar').hidden=route==='bundle';const b=document.getElementById('bottom-save');if(b)b.disabled=false;}
function toast(message){const e=document.createElement('div');e.className='toast';e.textContent=message;document.body.append(e);setTimeout(()=>e.remove(),2500);}
async function save(){if(rt.pending)return;let command;if(route==='bundle')command={op:'composition',...draft};else if(route==='product/desk-pair')command={op:'save_product',...draft};else if(route==='product/other')command={op:'other_status',status:draft.status};else{const key=route.split('/')[1],p=world.products[key];const changed=p.variants.filter(v=>draft.prices[v.id]!==v.price);for(const v of changed){const r=await rt.command({op:'component_price',product:key,variant:v.id,price:draft.prices[v.id]});if(!r?.ok)return;}initDraft();render();toast('Product saved');return;}const result=await rt.command(command);if(result?.ok){dirty=false;if(route==='bundle')route='product/desk-pair';initDraft();render();toast(result.message||'Product saved');}else{await rt.poll();render();}}
document.addEventListener('click',async e=>{const t=e.target.closest('button,a');if(!t)return;if(t.dataset.route){e.preventDefault();go(t.dataset.route);return;}if(t.dataset.remove){delete draft.components[t.dataset.remove];markDirty();render();return;}if(t.dataset.status){draft.status=t.dataset.status;markDirty();render();return;}switch(t.id){case 'save-bundle':case 'top-save':case 'bottom-save':await save();break;case 'discard':case 'reload':initDraft();render();break;case 'manage-publishing':modal={type:'publishing'};renderModal();break;case 'add-products':modal={type:'products'};renderModal();break;case 'close-modal':modal=null;renderModal();break;case 'done-publishing':draft.online=document.getElementById('channel-online').checked;markDirty();modal=null;render();break;case 'select-products':{const selected=[...document.querySelectorAll('[data-select-product]:checked')].map(x=>x.dataset.selectProduct),items={};for(const key of selected)items[key]=draft.components[key]||{quantity:1,selected:world.products[key].variants.map(v=>v.id)};draft.components=items;markDirty();modal=null;render();break;}case 'leave-page':{const next=modal.next;dirty=false;go(next);break;}}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='product-search'||t.id==='select-search'){const root=t.id==='select-search'?overlay:app;root.querySelectorAll('[data-search]').forEach(x=>x.hidden=!x.dataset.search.includes(t.value.toLowerCase()));return;}const f=t.dataset.edit;if(!f)return;if(f==='price'||f==='component-price'){draft.prices[t.dataset.key]=/^\d+(\.\d{0,2})?$/.test(t.value)?Math.round(Number(t.value)*100):null;}else if(f==='quantity')draft.components[t.dataset.key].quantity=Number(t.value);else if(f==='combined')draft.combined=t.checked;else if(f==='option'){const ids=draft.components[t.dataset.product].selected;draft.components[t.dataset.product].selected=t.checked?[...ids,t.dataset.key]:ids.filter(x=>x!==t.dataset.key);}markDirty();});
document.addEventListener('toggle',e=>{if(e.target.id==='order-components')orderExpanded=e.target.open;},true);
const rt=new RealtimeRuntime({scenario:task,episode,onState:s=>{world=s.world;renderClock(s);if(lastGeneration!==s.generation){lastGeneration=s.generation;lastVersion=s.version;route='product/desk-pair';modal=null;initDraft();render();return;}if(lastVersion!==s.version){lastVersion=s.version;if(!dirty)initDraft();render();}}});rt.start();
})();
